    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(address vader, address usdv, address vault) public {
        vm.assume(vader != address(0) && usdv != address(0) && vault != address(0));
        vm.prank(address(0x1234));
        c.init(vader, usdv, vault);
        bool ok;
        try c.init(vader, usdv, vault) { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }
